command -v python3>/dev/null 2>&1||apk add --no-cache python3;python3 -c 'import sys,json,math,zlib,time;k=int(sys.argv[1])if len(sys.argv)>1 else 4;c=int(sys.argv[2])if len(sys.argv)>2 else 12;n=k+1;ip=lambda x:x>1 and all(x%d for d in range(2,int(math.isqrt(x))+1));L=[];x=2;exec("while len(L)<n or x<c:\n L.extend([x]if ip(x)else[]);x+=1");p=L[n-1];Q=[q for q in range(c//2+1,c)if ip(q)];M=[{"P_m":q,"m":L.index(q)+1}for q in Q if q in L];E=[r for r in M if r["m"]==n];col=(c!=p and bool(E));H=0 if c==p else 1;O={"P":"CLZeroPack/RHMarkerEncodingMachine/Tiny/1","k":k,"n":n,"C_n":c,"P_n":p,"IntervalPrimes":M,"m_equals_k_plus_1_possible":bool(E),"IndexPreservingCollision":col,"TheoremGap":c!=p and not col,"H":H,"ZE":1-H,"Rb":"solved"if H==0 else"unsolved","TM":"halt_accept"if H==0 else"halt_review","RHProof":False,"Boundary":"Bertrand-Chebyshev does not force m=k+1","T":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())};O["CRC32"]=format(zlib.crc32(json.dumps(O,sort_keys=True,separators=(",",":")).encode())&0xffffffff,"08x");print(json.dumps(O,ensure_ascii=False,separators=(",",":")))' "$@"
